func (this *Bitstamp) GetCurrencyIdFromTransaction(transaction any) any {
	//
	//     {
	//         "fee": "0.00000000",
	//         "btc_usd": "0.00",
	//         "datetime": XXX,
	//         "usd": 0.0,
	//         "btc": 0.0,
	//         "eth": "0.05000000",
	//         "type": "0",
	//         "id": XXX,
	//         "eur": 0.0
	//     }
	//
	var currencyId *string = this.SafeStringLower(transaction, "currency")
	if currencyId != nil {
		return currencyId
	}
	var transactionOmitted map[string]any = MapTyped(this.Omit(transaction, []any{"fee", "price", "datetime", "type", "status", "id"}))
	var ids []string = ObjectKeys(transactionOmitted)
	for i := 0; i < len(ids); i++ {
		var id string = GetValue(ids, i).(string)
		if strings.Index(id, "_") < 0 {
			var value *int64 = this.SafeInteger(transactionOmitted, id)
			if (value != nil) && (value == nil || *value != 0) {
				return id
			}
		}
	}
	return nil
}
func (this *Bitstamp) GetMarketFromTrade(trade any) any {
	var tradeOmitted any = this.Omit(trade, []any{"fee", "price", "datetime", "tid", "type", "order_id", "side"})
	var currencyIds []string = ObjectKeys(tradeOmitted)
	var numCurrencyIds int = len(currencyIds)
	if numCurrencyIds > 2 {
		panic(ExchangeError(this.Id + " getMarketFromTrade() too many keys: " + this.Json(currencyIds) + " in the trade: " + this.Json(tradeOmitted)))
	}
	if numCurrencyIds == 2 {
		var marketId any = Add(GetValue(currencyIds, 0), GetValue(currencyIds, 1))
		if (this.Markets_by_id != nil) && (InOp(this.Markets_by_id, marketId)) {
			return this.SafeMarket(marketId)
		}
		marketId = Add(GetValue(currencyIds, 1), GetValue(currencyIds, 0))
		if (this.Markets_by_id != nil) && (InOp(this.Markets_by_id, marketId)) {
			return this.SafeMarket(marketId)
		}
	}
	return nil
}
func (this *Bitstamp) ParseTrade(trade any, optionalArgs ...any) any {
	//
	// fetchTrades (public)
	//
	//      {
	//          "date": "1637845199",
	//          "tid": "209895701",
	//          "amount": "0.00500000",
	//          "type": "0",             // Transaction type: 0 - buy; 1 - sell
	//          "price": "4451.25"
	//      }
	//
	// fetchMyTrades, trades returned within fetchOrder (private)
	//
	//      {
	//          "fee": "0.11128",
	//          "eth_usdt":  4451.25,
	//          "datetime": "2021-11-25 12:59:59.322000",
	//          "usdt": "-22.26",
	//          "order_id":  1429545880227846,
	//          "usd":  0,
	//          "btc":  0,
	//          "eth": "0.00500000",
	//          "type": "2",                    // Transaction type: 0 - deposit; 1 - withdrawal; 2 - market trade; 14 - sub account transfer; 25 - credited with staked assets; 26 - sent assets to staking; 27 - staking reward; 32 - referral reward; 35 - inter account transfer.
	//          "id":  209895701,
	//          "eur":  0
	//      }
	//
	// from fetchOrder (private)
	//
	//      {
	//          "fee": "0.11128",
	//          "price": "4451.25000000",
	//          "datetime": "2021-11-25 12:59:59.322000",
	//          "usdt": "22.25625000",
	//          "tid": 209895701,
	//          "eth": "0.00500000",
	//          "type": 2                       // Transaction type: 0 - deposit; 1 - withdrawal; 2 - market trade
	//      }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var id *string = this.SafeString2(trade, "id", "tid")
	var symbol *string = nil
	var side any = nil
	var priceString *string = this.SafeString(trade, "price")
	var amountString *string = this.SafeString(trade, "amount")
	var orderId *string = this.SafeString(trade, "order_id")
	var typeVar any = nil
	var costString *string = this.SafeString(trade, "cost")
	var rawMarketId any = nil
	// resolved in the key scan below, falling back to the passed market
	var marketResolved any = market
	if market == nil {
		var keys []string = ObjectKeys(trade)
		for i := 0; i < len(keys); i++ {
			var currentKey string = GetValue(keys, i).(string)
			if (currentKey != "order_id") && (strings.Index(currentKey, "_") >= 0) {
				rawMarketId = DerefScalar(currentKey)
				marketResolved = this.SafeMarket(rawMarketId, marketResolved, "_")
			}
		}
	}
	// if the market is still not defined
	// try to deduce it from used keys
	if IsEqual(marketResolved, nil) {
		marketResolved = this.GetMarketFromTrade(trade)
	}
	var feeCostString *string = this.SafeString(trade, "fee")
	var feeCurrency *string = this.SafeString(marketResolved, "quote")
	var priceId any = nil
	if rawMarketId != nil {
		priceId = rawMarketId
	} else {
		priceId = DerefScalar(this.SafeString(marketResolved, "id"))
	}
	priceString = this.SafeString(trade, priceId, priceString)
	amountString = this.SafeString(trade, this.SafeString(marketResolved, "baseId"), amountString)
	costString = this.SafeString(trade, this.SafeString(marketResolved, "quoteId"), costString)
	// this endpoint is not aligned with "markets" endpoint
	var baseIdLower *string = this.SafeStringLower(marketResolved, "baseId")
	var quoteIdLower *string = this.SafeStringLower(marketResolved, "quoteId")
	var dashedIdLower *string = SafeStringPtr(Add(Add(baseIdLower, "_"), quoteIdLower))
	if priceString == nil {
		priceString = this.SafeString(trade, dashedIdLower)
	}
	if amountString == nil {
		amountString = this.SafeString(trade, baseIdLower)
	}
	if costString == nil {
		costString = this.SafeString(trade, quoteIdLower)
	}
	symbol = this.SafeString(marketResolved, "symbol")
	var datetimeString *string = this.SafeString2(trade, "date", "datetime")
	var timestamp any = nil
	if datetimeString != nil {
		if func() int {
			if datetimeString == nil {
				return -1
			}
			return strings.Index(*datetimeString, " ")
		}() >= 0 {
			// iso8601
			timestamp = DerefScalar(this.Parse8601(datetimeString))
		} else {
			// string unix epoch in seconds
			timestamp = ParseInt(datetimeString)
			timestamp = Multiply(timestamp, 1000)
		}
	}
	// if it is a private trade
	if InOp(trade, "id") {
		if amountString != nil {
			var isAmountNeg bool = Precise.StringLt(amountString, "0")
			if isAmountNeg {
				side = "sell"
				amountString = Precise.StringNeg(amountString)
			} else {
				side = "buy"
			}
		}
	} else {
		side = DerefScalar(this.SafeString(trade, "type"))
		if IsEqual(side, "1") {
			side = "sell"
		} else if IsEqual(side, "0") {
			side = "buy"
		} else {
			side = nil
		}
	}
	if costString != nil {
		costString = Precise.StringAbs(costString)
	}
	var fee map[string]any = nil
	if feeCostString != nil {
		fee = map[string]any{
			"cost":     feeCostString,
			"currency": feeCurrency,
		}
	}
	return this.SafeTrade(map[string]any{
		"id":           id,
		"info":         trade,
		"timestamp":    timestamp,
		"datetime":     this.Iso8601(timestamp),
		"symbol":       symbol,
		"order":        orderId,
		"type":         typeVar,
		"side":         side,
		"takerOrMaker": nil,
		"price":        priceString,
		"amount":       amountString,
		"cost":         costString,
		"fee":          fee,
	}, marketResolved)
}

/**
 * @method
 * @name bitstamp#fetchTrades
 * @description get the list of most recent trades for a particular symbol
 * @see https://www.bitstamp.net/api/#tag/Transactions-public/operation/GetTransactions
 * @param {string} symbol unified symbol of the market to fetch trades for
 * @param {int} [since] timestamp in ms of the earliest trade to fetch
 * @param {int} [limit] the maximum amount of trades to fetch
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {Trade[]} a list of [trade structures]{@link https://docs.ccxt.com/?id=public-trades}
 */
func (this *Bitstamp) FetchTradesAsync(symbol any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchTradesBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Bitstamp) fetchTradesBody(ch chan any, symbol any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var since *int64 = GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 2, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"pair": market["id"],
		"time": "hour",
	}

	var response []any = ListTyped(PanicOnError((<-this.PublicGetTransactionsPair(this.Extend(request, params))).Raw))

	//
	//     [
	//         {
	//             "date": "1551814435",
	//             "tid": "83581898",
	//             "price": "0.03532850",
	//             "type": "1",
	//             "amount": "0.85945907"
	//         },
	//         {
	//             "date": "1551814434",
	//             "tid": "83581896",
	//             "price": "0.03532851",
	//             "type": "1",
	//             "amount": "11.34130961"
	//         },
	//     ]
	//
	ch <- this.ParseTrades(response, market, since, limit)
	return nil
}
func (this *Bitstamp) ParseOHLCV(ohlcv any, optionalArgs ...any) any {
	//
	//     {
	//         "high": "9064.77",
	//         "timestamp": "1593961440",
	//         "volume": "18.49436608",
	//         "low": "9040.87",
	//         "close": "9064.77",
	//         "open": "9040.87"
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	return []any{this.SafeTimestamp(ohlcv, "timestamp"), this.SafeNumber(ohlcv, "open"), this.SafeNumber(ohlcv, "high"), this.SafeNumber(ohlcv, "low"), this.SafeNumber(ohlcv, "close"), this.SafeNumber(ohlcv, "volume")}
}

/**
 * @method
 * @name bitstamp#fetchOHLCV
 * @description fetches historical candlestick data containing the open, high, low, and close price, and the volume of a market
 * @see https://www.bitstamp.net/api/#tag/Market-info/operation/GetOHLCData
 * @param {string} symbol unified symbol of the market to fetch OHLCV data for
 * @param {string} timeframe the length of time each candle represents
 * @param {int} [since] timestamp in ms of the earliest candle to fetch
 * @param {int} [limit] the maximum amount of candles to fetch
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {int} [params.until] timestamp in ms of the latest candle to fetch
 * @returns {int[][]} A list of candles ordered as timestamp, open, high, low, close, volume
 */
func (this *Bitstamp) FetchOHLCVAsync(symbol string, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchOHLCVBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Bitstamp) fetchOHLCVBody(ch chan any, symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var timeframe string = GetArgString(optionalArgs, 0, "1m")
	_ = timeframe
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"pair": market["id"],
		"step": this.SafeString(this.Timeframes, timeframe, timeframe),
	}
	var duration int64 = this.ParseTimeframe(timeframe)
	var until *int64 = this.SafeInteger(params, "until")
	var untilIsDefined bool = (until != nil)
	var limitResolved any = func() any {
		if limit == nil {
			return 1000
		}
		return limit
	}()
	if limit == nil {
		if since == nil {
			request["limit"] = limitResolved
			if untilIsDefined {
				var end any = this.ParseToInt(Divide(until, 1000))
				request["start"] = Subtract(Subtract(end, (Multiply(duration, limitResolved))), 1)
				request["end"] = end
			}
		} else {
			var start int64 = this.ParseToInt(Divide(since, 1000))
			request["start"] = start
			if untilIsDefined {
				request["end"] = this.ParseToInt(Divide(until, 1000))
			} else {
				request["end"] = this.Sum(start, Subtract(Multiply(duration, limitResolved), 1))
			}
			request["limit"] = limitResolved
		}
	} else {
		if since != nil {
			var start int64 = this.ParseToInt(Divide(since, 1000))
			request["start"] = start
			var end any = this.Sum(start, Subtract(Multiply(duration, limitResolved), 1))
			if untilIsDefined {
				end = mathMin(end, this.ParseToInt(Divide(until, 1000)))
			}
			request["end"] = end
		} else if untilIsDefined {
			var end any = this.ParseToInt(Divide(until, 1000))
			request["end"] = end
			request["start"] = Subtract(Subtract(end, (Multiply(duration, limitResolved))), 1)
		}
		request["limit"] = mathMin(limitResolved, 1000) // min 1, max 1000
	}
	var paramsOmitted map[string]any = MapTyped(this.Omit(params, "until"))

	var response map[string]any = MapTyped(PanicOnError((<-this.PublicGetOhlcPair(this.Extend(request, paramsOmitted))).Raw))
	//
	//     {
	//         "data": {
	//             "pair": "BTC/USD",
	//             "ohlc": [
	//                 {"high": "9064.77", "timestamp": "1593961440", "volume": "18.49436608", "low": "9040.87", "close": "9064.77", "open": "9040.87"},
	//                 {"high": "9071.59", "timestamp": "1593961500", "volume": "3.48631711", "low": "9058.76", "close": "9061.07", "open": "9064.66"},
	//                 {"high": "9067.33", "timestamp": "1593961560", "volume": "0.04142833", "low": "9061.94", "close": "9061.94", "open": "9067.33"},
	//             ],
	//         }
	//     }
	//
	var data map[string]any = SafeMapTyped(response, "data")
	var ohlc []any = SafeListTypedDefault(data, "ohlc", []any{})

	ch <- this.ParseOHLCVs(ohlc, market, timeframe, since, limitResolved)
	return nil
}
func (this *Bitstamp) ParseBalance(response any) any {
	var finalResponse any = response // java req
	var result map[string]any = map[string]any{
		"info":      finalResponse,
		"timestamp": nil,
		"datetime":  nil,
	}
	var responseList any = response
	if IsEqual(response, nil) {
		responseList = []any{}
	}
	for i := 0; i < GetArrayLength(responseList); i++ {
		var currencyBalance map[string]any = SafeMapTyped(responseList, i)
		var currencyId *string = this.SafeString(currencyBalance, "currency")
		var currencyCode *string = this.SafeCurrencyCode(currencyId)
		var account map[string]any = this.Account()
		account["free"] = this.SafeString(currencyBalance, "available")
		account["used"] = this.SafeString(currencyBalance, "reserved")
		account["total"] = this.SafeString(currencyBalance, "total")
		if currencyCode != nil {
			result[*currencyCode] = account
		}
	}
	return this.SafeBalance(result)
}

