/**
 * @method
 * @name bitstamp#fetchTradingFee
 * @description fetch the trading fees for a market
 * @see https://www.bitstamp.net/api/#tag/Fees/operation/GetTradingFeesForCurrency
 * @param {string} symbol unified market symbol
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [fee structure]{@link https://docs.ccxt.com/?id=fee-structure}
 */
func (this *Bitstamp) FetchTradingFeeAsync(symbol string, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchTradingFeeBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Bitstamp) fetchTradingFeeBody(ch chan any, symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"market_symbol": market["id"],
	}

	var response []any = ListTyped(PanicOnError((<-this.PrivatePostFeesTrading(this.Extend(request, params))).Raw))
	//
	//     [
	//         {
	//             "currency_pair": "btcusd",
	//             "fees":
	//                 {
	//                     "maker": "0.15000",
	//                     "taker": "0.16000"
	//                 },
	//             "market": "btcusd"
	//         }
	//         ...
	//     ]
	//
	var tradingFeesByMarketId map[string]any = this.IndexBy(response, "currency_pair")
	var tradingFee any = this.SafeDict(tradingFeesByMarketId, market["id"])
	if IsEqual(tradingFee, nil) {
		tradingFee = map[string]any{}
	}

	ch <- this.ParseTradingFee(tradingFee, market)
	return nil
}
func (this *Bitstamp) ParseTradingFee(fee any, optionalArgs ...any) any {
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var marketId *string = this.SafeString(fee, "market")
	var fees map[string]any = SafeMapTyped(fee, "fees")
	return map[string]any{
		"info":       fee,
		"symbol":     this.SafeSymbol(marketId, market),
		"maker":      this.SafeNumber(fees, "maker"),
		"taker":      this.SafeNumber(fees, "taker"),
		"percentage": nil,
		"tierBased":  nil,
	}
}
func (this *Bitstamp) ParseTradingFees(fees any) map[string]any {
	var result map[string]any = map[string]any{
		"info": fees,
	}
	for i := 0; i < GetArrayLength(fees); i++ {
		var fee any = this.ParseTradingFee(GetValue(fees, i))
		var symbol *string = SafeStringPtr(GetValue(fee, "symbol"))
		if symbol != nil {
			AddElementToObject(result, symbol, fee)
		}
	}
	return result
}

