func (this *Bitstamp) fetchTransactionFeesBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var codes []string = GetArgStringSlice(optionalArgs, 0, nil)
	_ = codes
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}

	var response []any = ListTyped(PanicOnError((<-this.PrivatePostFeesWithdrawal(params)).Raw))

	//
	//     [
	//         {
	//             "currency": "btc",
	//             "fee": "0.00015000",
	//             "network": "bitcoin"
	//         }
	//         ...
	//     ]
	//
	ch <- this.ParseTransactionFees(response)
	return nil
}
func (this *Bitstamp) ParseTransactionFees(response any, optionalArgs ...any) map[string]any {
	var codes []string = GetArgStringSlice(optionalArgs, 0, nil)
	_ = codes
	var result map[string]any = map[string]any{}
	var currencies map[string]any = this.IndexBy(response, "currency")
	var ids []string = ObjectKeys(currencies)
	for i := 0; i < len(ids); i++ {
		var id string = GetValue(ids, i).(string)
		var fees map[string]any = SafeMapTyped(response, i)
		var code *string = this.SafeCurrencyCode(id)
		if (codes != nil) && !this.InArray(code, codes) {
			continue
		}
		if code != nil {
			result[*code] = map[string]any{
				"withdraw_fee": this.SafeNumber(fees, "fee"),
				"deposit":      map[string]any{},
				"info":         this.SafeDict(currencies, id),
			}
		}
	}
	return result
}

/**
 * @method
 * @name bitstamp#fetchDepositWithdrawFees
 * @description fetch deposit and withdraw fees
 * @see https://www.bitstamp.net/api/#tag/Fees/operation/GetAllWithdrawalFees
 * @param {string[]|undefined} codes list of unified currency codes
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object[]} a list of [fee structures]{@link https://docs.ccxt.com/?id=fee-structure}
 */
func (this *Bitstamp) FetchDepositWithdrawFeesAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchDepositWithdrawFeesBody(ch, optionalArgs...)
	return ch
}
func (this *Bitstamp) fetchDepositWithdrawFeesBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var codes []string = GetArgStringSlice(optionalArgs, 0, nil)
	_ = codes
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}

	var response []any = ListTyped(PanicOnError((<-this.PrivatePostFeesWithdrawal(params)).Raw))
	//
	//     [
	//         {
	//             "currency": "btc",
	//             "fee": "0.00015000",
	//             "network": "bitcoin"
	//         }
	//         ...
	//     ]
	//
	var responseByCurrencyId map[string]any = this.GroupBy(response, "currency")

	ch <- this.ParseDepositWithdrawFees(responseByCurrencyId, codes)
	return nil
}
func (this *Bitstamp) ParseDepositWithdrawFee(fee any, optionalArgs ...any) any {
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var result any = this.DepositWithdrawFee(fee)
	var code *string = this.SafeString(currency, "code")
	for j := 0; j < GetArrayLength(fee); j++ {
		var networkEntry map[string]any = SafeMapTyped(fee, j)
		var networkId *string = this.SafeString(networkEntry, "network")
		var networkCode *string = this.NetworkIdToCode(networkId, code)
		var withdrawFee *float64 = this.SafeNumber(networkEntry, "fee")
		AddElementToObject(result, "withdraw", map[string]any{
			"fee":        withdrawFee,
			"percentage": nil,
		})
		if networkCode != nil {
			AddElementToObject(GetValue(result, "networks"), networkCode, map[string]any{
				"withdraw": map[string]any{
					"fee":        withdrawFee,
					"percentage": nil,
				},
				"deposit": map[string]any{
					"fee":        nil,
					"percentage": nil,
				},
			})
		}
	}
	return result
}

/**
 * @method
 * @name bitstamp#createOrder
 * @description create a trade order
 * @see https://www.bitstamp.net/api/#tag/Orders/operation/OpenInstantBuyOrder
 * @see https://www.bitstamp.net/api/#tag/Orders/operation/OpenMarketBuyOrder
 * @see https://www.bitstamp.net/api/#tag/Orders/operation/OpenLimitBuyOrder
 * @see https://www.bitstamp.net/api/#tag/Orders/operation/OpenInstantSellOrder
 * @see https://www.bitstamp.net/api/#tag/Orders/operation/OpenMarketSellOrder
 * @see https://www.bitstamp.net/api/#tag/Orders/operation/OpenLimitSellOrder
 * @param {string} symbol unified symbol of the market to create an order in
 * @param {string} type 'market' or 'limit'
 * @param {string} side 'buy' or 'sell'
 * @param {float} amount how much of currency you want to trade in units of base currency
 * @param {float} [price] the price at which the order is to be fulfilled, in units of the quote currency, ignored in market orders
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} an [order structure]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Bitstamp) CreateOrderAsync(symbol string, typeVar string, side string, amount any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.createOrderBody(ch, symbol, typeVar, side, amount, optionalArgs...)
	return ch
}
func (this *Bitstamp) createOrderBody(ch chan any, symbol string, typeVar string, side string, amount any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var price *float64 = GetArgFloat64Ptr(optionalArgs, 0, nil)
	_ = price
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"pair":   market["id"],
		"amount": this.AmountToPrecision(symbol, amount),
	}
	var clientOrderId *string = this.SafeString2(params, "client_order_id", "clientOrderId")
	if clientOrderId != nil {
		request["client_order_id"] = clientOrderId
	}
	var paramsOmitted map[string]any = func() map[string]any {
		if clientOrderId != nil {
			return MapTyped(this.Omit(params, []any{"clientOrderId"}))
		}
		return params
	}()
	var response map[string]any = nil
	var capitalizedSide string = this.Capitalize(side)
	if typeVar == "market" {
		if capitalizedSide == "Buy" {

			response = MapTyped(PanicOnError((<-this.PrivatePostBuyMarketPair(this.Extend(request, paramsOmitted))).Raw))
		} else {

			response = MapTyped(PanicOnError((<-this.PrivatePostSellMarketPair(this.Extend(request, paramsOmitted))).Raw))
		}
	} else if typeVar == "instant" {
		if capitalizedSide == "Buy" {

			response = MapTyped(PanicOnError((<-this.PrivatePostBuyInstantPair(this.Extend(request, paramsOmitted))).Raw))
		} else {

			response = MapTyped(PanicOnError((<-this.PrivatePostSellInstantPair(this.Extend(request, paramsOmitted))).Raw))
		}
	} else {
		request["price"] = this.PriceToPrecision(symbol, price)
		if capitalizedSide == "Buy" {

			response = MapTyped(PanicOnError((<-this.PrivatePostBuyPair(this.Extend(request, paramsOmitted))).Raw))
		} else {

			response = MapTyped(PanicOnError((<-this.PrivatePostSellPair(this.Extend(request, paramsOmitted))).Raw))
		}
	}
	var orderResponse any = func() any {
		if response == nil {
			return map[string]any{}
		}
		return response
	}()
	var order map[string]any = MapTyped(this.ParseOrder(orderResponse, market))
	order["type"] = typeVar

	ch <- order
	return nil
}

/**
 * @method
 * @name bitstamp#editOrder
 * @description edit a trade order
 * @see https://www.bitstamp.net/api/#tag/Orders/operation/ReplaceOrder
 * @param {string} id order id
 * @param {string} [symbol] unified symbol of the market to create an order in
 * @param {string} [type] 'market', 'limit' or 'stop_limit'
 * @param {string} [side] 'buy' or 'sell'
 * @param {float} [amount] how much of the currency you want to trade in units of the base currency
 * @param {float} [price] the price for the order, in units of the quote currency, ignored in market orders
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.triggerPrice] the price to trigger a stop order
 * @param {string} [params.timeInForce] for crypto trading either 'gtc' or 'ioc' can be used
 * @param {string} [params.clientOrderId] a unique identifier for the order, automatically generated if not sent
 * @returns {object} an [order structure]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Bitstamp) EditOrderAsync(id string, symbol any, typeVar any, side any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.editOrderBody(ch, id, symbol, typeVar, side, optionalArgs...)
	return ch
}
func (this *Bitstamp) editOrderBody(ch chan any, id string, symbol any, typeVar any, side any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var amount *float64 = GetArgFloat64Ptr(optionalArgs, 0, nil)
	_ = amount
	var price *float64 = GetArgFloat64Ptr(optionalArgs, 1, nil)
	_ = price
	var params map[string]any = GetArgMap(optionalArgs, 2, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"amount": this.AmountToPrecision(symbol, amount),
		"price":  this.PriceToPrecision(symbol, price),
	}
	var clientOrderId *string = this.SafeString2(params, "client_order_id", "clientOrderId")
	if clientOrderId != nil {
		request["client_order_id"] = clientOrderId
	} else {
		request["id"] = id
	}
	var paramsOmitted map[string]any = func() map[string]any {
		if clientOrderId != nil {
			return MapTyped(this.Omit(params, []any{"clientOrderId"}))
		}
		return params
	}()

	var response map[string]any = MapTyped(PanicOnError((<-this.PrivatePostReplaceOrder(this.Extend(request, paramsOmitted))).Raw))
	var order map[string]any = MapTyped(this.ParseOrder(response, market))
	order["type"] = typeVar

	ch <- order
	return nil
}

