func (this *Bitstamp) cancelAllOrdersBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbol *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var market map[string]any = nil
	var request map[string]any = map[string]any{}
	var response map[string]any = nil
	if symbol != nil {
		market = this.Market(symbol)
		request["pair"] = GetValue(market, "id")

		response = MapTyped(PanicOnError((<-this.PrivatePostCancelAllOrdersPair(this.Extend(request, params))).Raw))
	} else {

		response = MapTyped(PanicOnError((<-this.PrivatePostCancelAllOrders(this.Extend(request, params))).Raw))
	}
	//
	//    {
	//        "canceled": [
	//            {
	//                "id": 1453282316578816,
	//                "amount": "0.02035278",
	//                "price": "2100.45",
	//                "type": 0,
	//                "currency_pair": "BTC/USD",
	//                "market": "BTC/USD"
	//            }
	//        ],
	//        "success": true
	//    }
	//
	var canceled []any = SafeListTyped(response, "canceled")

	ch <- this.ParseOrders(canceled)
	return nil
}
func (this *Bitstamp) ParseOrderStatus(status *string) *string {
	var statuses map[string]any = map[string]any{
		"In Queue":       "open",
		"Open":           "open",
		"Finished":       "closed",
		"Canceled":       "canceled",
		"Cancel pending": "canceling",
	}
	return this.SafeString(statuses, status, status)
}
