func (this *Bitstamp) ParseTransaction(transaction any, optionalArgs ...any) any {
	//
	// fetchDepositsWithdrawals
	//
	//     {
	//         "fee": "0.00000000",
	//         "btc_usd": "0.00",
	//         "id": 1234567894,
	//         "usd": 0,
	//         "btc": 0,
	//         "datetime": "2018-09-08 09:00:31",
	//         "type": "1",
	//         "xrp": "-20.00000000",
	//         "eur": 0,
	//     }
	//
	// fetchWithdrawals
	//
	//     {
	//         "status": 2,
	//         "datetime": "2018-10-17 10:58:13",
	//         "currency": "BTC",
	//         "amount": "0.29669259",
	//         "address": "aaaaa",
	//         "type": 1,
	//         "id": 111111,
	//         "transaction_id": "xxxx",
	//     }
	//
	//     {
	//         "id": 3386432,
	//         "type": 14,
	//         "amount": "863.21332500",
	//         "status": 2,
	//         "address": "rE1sdh25BJQ3qFwngiTBwaq3zPGGYcrjp1?dt=1455",
	//         "currency": "XRP",
	//         "datetime": "2018-01-05 15:27:55",
	//         "transaction_id": "001743B03B0C79BA166A064AC0142917B050347B4CB23BA2AB4B91B3C5608F4C"
	//     }
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var timestamp *int64 = this.Parse8601(this.SafeString(transaction, "datetime"))
	var currencyId any = this.GetCurrencyIdFromTransaction(transaction)
	var code *string = this.SafeCurrencyCode(currencyId, currency)
	var feeCost *string = this.SafeString(transaction, "fee")
	var feeCurrency any = nil
	var amount any = nil
	if InOp(transaction, "amount") {
		amount = DerefScalar(this.SafeString(transaction, "amount"))
	} else if currency != nil {
		amount = DerefScalar(this.SafeString(transaction, GetValue(currency, "id"), amount))
		feeCurrency = GetValue(currency, "code")
	} else if (code != nil) && (currencyId != nil) {
		amount = DerefScalar(this.SafeString(transaction, currencyId, amount))
		feeCurrency = code
	}
	if !IsEqual(amount, nil) {
		// withdrawals have a negative amount
		amount = Precise.StringAbs(amount)
	}
	var status any = "ok"
	if InOp(transaction, "status") {
		status = this.ParseTransactionStatus(this.SafeString(transaction, "status"))
	}
	var typeVar *string = nil
	if InOp(transaction, "type") {
		// from fetchDepositsWithdrawals
		var rawType *string = this.SafeString(transaction, "type")
		if rawType != nil && *rawType == "0" {
			typeVar = SafeStringPtr("deposit")
		} else if rawType != nil && *rawType == "1" {
			typeVar = SafeStringPtr("withdrawal")
		}
	} else {
		// from fetchWithdrawals
		typeVar = SafeStringPtr("withdrawal")
	}
	var tag any = nil
	var address any = DerefScalar(this.SafeString(transaction, "address"))
	if !IsEqual(address, nil) {
		// dt (destination tag) is embedded into the address field
		var addressParts []string = Split(address, "?dt=")
		var numParts int = len(addressParts)
		if numParts > 1 {
			address = GetValue(addressParts, 0)
			tag = GetValue(addressParts, 1)
		}
	}
	var fee map[string]any = map[string]any{
		"currency": nil,
		"cost":     nil,
		"rate":     nil,
	}
	if feeCost != nil {
		fee = map[string]any{
			"currency": feeCurrency,
			"cost":     feeCost,
			"rate":     nil,
		}
	}
	return map[string]any{
		"info":        transaction,
		"id":          this.SafeString(transaction, "id"),
		"txid":        this.SafeString(transaction, "transaction_id"),
		"type":        typeVar,
		"currency":    code,
		"network":     nil,
		"amount":      this.ParseNumber(amount),
		"status":      status,
		"timestamp":   timestamp,
		"datetime":    this.Iso8601(timestamp),
		"address":     address,
		"addressFrom": nil,
		"addressTo":   address,
		"tag":         tag,
		"tagFrom":     nil,
		"tagTo":       tag,
		"updated":     nil,
		"comment":     nil,
		"internal":    nil,
		"fee":         fee,
	}
}
func (this *Bitstamp) ParseTransactionStatus(status *string) *string {
	//
	//   withdrawals:
	//   0 (open), 1 (in process), 2 (finished), 3 (canceled) or 4 (failed).
	//
	var statuses map[string]any = map[string]any{
		"0": "pending",
		"1": "pending",
		"2": "ok",
		"3": "canceled",
		"4": "failed",
	}
	return this.SafeString(statuses, status, status)
}
func (this *Bitstamp) ParseOrder(order any, optionalArgs ...any) any {
	//
	//   from fetch order:
	//     { status: "Finished",
	//       "id": 731693945,
	//       "client_order_id": '',
	//       "transactions":
	//       [ { fee: "0.000019",
	//           "price": "0.00015803",
	//           "datetime": "2018-01-07 10:45:34.132551",
	//           "btc": "0.0079015000000000",
	//           "tid": 42777395,
	//           "type": 2,
	//           "xrp": "50.00000000" } ] }
	//
	//   partially filled order:
	//     { "id": 468646390,
	//       "client_order_id": "",
	//       "status": "Canceled",
	//       "transactions": [{
	//           "eth": "0.23000000",
	//           "fee": "0.09",
	//           "tid": 25810126,
	//           "usd": "69.8947000000000000",
	//           "type": 2,
	//           "price": "303.89000000",
	//           "datetime": "2017-11-11 07:22:20.710567"
	//       }]}
	//
	//   from create order response:
	//       {
	//           "price": "0.00008012",
	//           "client_order_id": '',
	//           "currency_pair": "XRP/BTC",
	//           "datetime": "2019-01-31 21:23:36",
	//           "amount": "15.00000000",
	//           "type": "0",
	//           "id": "2814205012"
	//       }
	//
	// cancelOrder
	//
	//    {
	//        "id": 1453282316578816,
	//        "amount": "0.02035278",
	//        "price": "2100.45",
	//        "type": 0,
	//        "market": "BTC/USD"
	//    }
	//
	// editOrder
	//
	//    {
	//        "order_id": 1453282316578816,
	//        "order_type": "0",
	//        "market": "BTC/USD",
	//        "amount": "0.02035278",
	//        "price": "2100.45",
	//        "datetime": "2025-10-17T14:23:01.725000Z",
	//        "orig_order_id": 1453282316578816,
	//        "orig_client_order_id": "my-original-order-123",
	//        "status": "Open"
	//    }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var id *string = this.SafeString2(order, "id", "order_id")
	var clientOrderId *string = this.SafeString2(order, "client_order_id", "orig_client_order_id")
	var side *string = this.SafeString2(order, "type", "order_type")
	if side != nil {
		side = SafeStringPtr(func() string {
			if side != nil && *side == "1" {
				return "sell"
			}
			return "buy"
		}())
	}
	// there is no timestamp from fetchOrder
	var timestamp *int64 = this.Parse8601(this.SafeString(order, "datetime"))
	var marketId *string = this.SafeStringLower(order, "currency_pair")
	var symbol *string = this.SafeSymbol(marketId, market, "/")
	var status *string = this.ParseOrderStatus(this.SafeString(order, "status"))
	var amount *string = this.SafeString(order, "amount")
	var transactions []any = SafeListTypedDefault(order, "transactions", []any{})
	var price *string = this.SafeString(order, "price")
	return this.SafeOrder(map[string]any{
		"id":                 id,
		"clientOrderId":      clientOrderId,
		"datetime":           this.Iso8601(timestamp),
		"timestamp":          timestamp,
		"lastTradeTimestamp": nil,
		"status":             status,
		"symbol":             symbol,
		"type":               nil,
		"timeInForce":        nil,
		"postOnly":           nil,
		"side":               side,
		"price":              price,
		"triggerPrice":       nil,
		"cost":               nil,
		"amount":             amount,
		"filled":             nil,
		"remaining":          nil,
		"trades":             transactions,
		"fee":                nil,
		"info":               order,
		"average":            nil,
	}, market)
}
func (this *Bitstamp) ParseLedgerEntryType(typeVar *string) *string {
	var types map[string]any = map[string]any{
		"0":  "transaction",
		"1":  "transaction",
		"2":  "trade",
		"14": "transfer",
	}
	return this.SafeString(types, typeVar, typeVar)
}
func (this *Bitstamp) ParseLedgerEntry(item any, optionalArgs ...any) any {
	//
	//     [
	//         {
	//             "fee": "0.00000000",
	//             "btc_usd": "0.00",
	//             "id": 1234567894,
	//             "usd": 0,
	//             "btc": 0,
	//             "datetime": "2018-09-08 09:00:31",
	//             "type": "1",
	//             "xrp": "-20.00000000",
	//             "eur": 0,
	//         },
	//         {
	//             "fee": "0.00000000",
	//             "btc_usd": "0.00",
	//             "id": 1134567891,
	//             "usd": 0,
	//             "btc": 0,
	//             "datetime": "2018-09-07 18:47:52",
	//             "type": "0",
	//             "xrp": "20.00000000",
	//             "eur": 0,
	//         },
	//     ]
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var typeVar *string = this.ParseLedgerEntryType(this.SafeString(item, "type"))
	if typeVar != nil && *typeVar == "trade" {
		var parsedTrade map[string]any = MapTyped(this.ParseTrade(item))
		var market any = nil
		var keys []string = ObjectKeys(item)
		for i := 0; i < len(keys); i++ {
			if GetIndexOf(GetValue(keys, i), "_") >= 0 {
				var marketId string = Replace(GetValue(keys, i), "_", "")
				market = this.SafeMarket(marketId, market)
			}
		}
		// if the market is still not defined
		// try to deduce it from used keys
		if IsEqual(market, nil) {
			market = this.GetMarketFromTrade(item)
		}
		var direction string = func() string {
			if IsEqual(parsedTrade["side"], "buy") {
				return "in"
			}
			return "out"
		}()
		return this.SafeLedgerEntry(map[string]any{
			"info":             item,
			"id":               parsedTrade["id"],
			"timestamp":        parsedTrade["timestamp"],
			"datetime":         parsedTrade["datetime"],
			"direction":        direction,
			"account":          nil,
			"referenceId":      parsedTrade["order"],
			"referenceAccount": nil,
			"type":             typeVar,
			"currency":         this.SafeString(market, "base"),
			"amount":           parsedTrade["amount"],
			"before":           nil,
			"after":            nil,
			"status":           "ok",
			"fee":              parsedTrade["fee"],
		}, currency)
	} else {
		var parsedTransaction map[string]any = MapTyped(this.ParseTransaction(item, currency))
		var direction any = nil
		var hasTransactionCurrency bool = !(InOp(item, "amount")) && (func() bool { _, ok := parsedTransaction["currency"]; return ok }()) && (!IsEqual(parsedTransaction["currency"], nil))
		var currencyResolved any = currency
		if hasTransactionCurrency {
			currencyResolved = this.Currency(this.SafeString(parsedTransaction, "currency"))
		}
		if InOp(item, "amount") {
			var amount *string = this.SafeString(item, "amount")
			direction = func() string {
				if Precise.StringGt(amount, "0") {
					return "in"
				}
				return "out"
			}()
		} else if (func() bool { _, ok := parsedTransaction["currency"]; return ok }()) && !IsEqual(parsedTransaction["currency"], nil) {
			var amount *string = this.SafeString(item, this.SafeString(currencyResolved, "id"))
			direction = func() string {
				if Precise.StringGt(amount, "0") {
					return "in"
				}
				return "out"
			}()
		}
		return this.SafeLedgerEntry(map[string]any{
			"info":             item,
			"id":               parsedTransaction["id"],
			"timestamp":        parsedTransaction["timestamp"],
			"datetime":         parsedTransaction["datetime"],
			"direction":        direction,
			"account":          nil,
			"referenceId":      parsedTransaction["txid"],
			"referenceAccount": nil,
			"type":             typeVar,
			"currency":         parsedTransaction["currency"],
			"amount":           parsedTransaction["amount"],
			"before":           nil,
			"after":            nil,
			"status":           parsedTransaction["status"],
			"fee":              parsedTransaction["fee"],
		}, currencyResolved)
	}
}

/**
 * @method
 * @name bitstamp#fetchLedger
 * @description fetch the history of changes, actions done by the user or operations that altered the balance of the user
 * @see https://www.bitstamp.net/api/#tag/Transactions-private/operation/GetUserTransactions
 * @param {string} [code] unified currency code, default is undefined
 * @param {int} [since] timestamp in ms of the earliest ledger entry, default is undefined
 * @param {int} [limit] max number of ledger entries to return, default is undefined
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [ledger structure]{@link https://docs.ccxt.com/?id=ledger-entry-structure}
 */
func (this *Bitstamp) FetchLedgerAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchLedgerBody(ch, optionalArgs...)
	return ch
}
func (this *Bitstamp) fetchLedgerBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var code *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = code
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var request map[string]any = map[string]any{}
	if limit != nil {
		request["limit"] = limit
	}

	var response []any = ListTyped(PanicOnError((<-this.PrivatePostUserTransactions(this.Extend(request, params))).Raw))
	var currency map[string]any = nil
	if code != nil {
		currency = this.Currency(code)
	}

	ch <- this.ParseLedger(response, currency, since, limit)
	return nil
}

/**
 * @method
 * @name bitstamp#fetchFundingRate
 * @description fetch the current funding rate
 * @see https://www.bitstamp.net/api/#tag/Market-info/operation/GetFundingRate
 * @param {string} symbol unified market symbol
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [funding rate structure]{@link https://docs.ccxt.com/?id=funding-rate-structure}
 */
func (this *Bitstamp) FetchFundingRateAsync(symbol string, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchFundingRateBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Bitstamp) fetchFundingRateBody(ch chan any, symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"market_symbol": market["id"],
	}

	var response map[string]any = MapTyped(PanicOnError((<-this.PublicGetFundingRateMarketSymbol(this.Extend(request, params))).Raw))

	//
	//     {
	//         "funding_rate": "0.0024",
	//         "timestamp": "1644406050",
	//         "market": "BTC/USD-PERP",
	//         "next_funding_time": "1644406050"
	//     }
	//
	ch <- this.ParseFundingRate(response, market)
	return nil
}
func (this *Bitstamp) ParseFundingRate(fundingRate any, optionalArgs ...any) any {
	//
	//     {
	//         "funding_rate": "0.0024",
	//         "timestamp": "1644406050",
	//         "market": "BTC/USD-PERP",
	//         "next_funding_time": "1644406050"
	//     }
	//
	// the websocket funding_rate channel additionally carries mark_price and index_price
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var currentTime *int64 = this.SafeIntegerProduct(fundingRate, "timestamp", 1000)
	var nextFundingRateTimestamp *int64 = this.SafeIntegerProduct(fundingRate, "next_funding_time", 1000)
	var marketId *string = this.SafeString(fundingRate, "market")
	return map[string]any{
		"info":                     fundingRate,
		"symbol":                   this.SafeSymbol(marketId, market),
		"markPrice":                this.SafeNumber(fundingRate, "mark_price"),
		"indexPrice":               this.SafeNumber(fundingRate, "index_price"),
		"interestRate":             nil,
		"estimatedSettlePrice":     nil,
		"timestamp":                currentTime,
		"datetime":                 this.Iso8601(currentTime),
		"previousFundingRate":      nil,
		"nextFundingRate":          nil,
		"previousFundingTimestamp": nil,
		"nextFundingTimestamp":     nil,
		"previousFundingDatetime":  nil,
		"nextFundingDatetime":      nil,
		"fundingRate":              this.SafeNumber(fundingRate, "funding_rate"),
		"fundingTimestamp":         nextFundingRateTimestamp,
		"fundingDatetime":          this.Iso8601(nextFundingRateTimestamp),
		"interval":                 nil,
	}
}

/**
 * @method
 * @name bitstamp#fetchOpenOrders
 * @description fetch all unfilled currently open orders
 * @see https://www.bitstamp.net/api/#tag/Orders/operation/GetAllOpenOrders
 * @see https://www.bitstamp.net/api/#tag/Orders/operation/GetOpenOrdersForMarket
 * @param {string} symbol unified market symbol
 * @param {int} [since] the earliest time in ms to fetch open orders for
 * @param {int} [limit] the maximum number of  open orders structures to retrieve
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {Order[]} a list of [order structures]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Bitstamp) FetchOpenOrdersAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchOpenOrdersBody(ch, optionalArgs...)
	return ch
}
func (this *Bitstamp) fetchOpenOrdersBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbol *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	var market map[string]any = nil
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	if symbol != nil {
		market = this.Market(symbol)
	}

	var response []any = ListTyped(PanicOnError((<-this.PrivatePostOpenOrdersAll(params)).Raw))

	//
	//     [
	//         {
	//             "price": "0.00008012",
	//             "currency_pair": "XRP/BTC",
	//             "client_order_id": '',
	//             "datetime": "2019-01-31 21:23:36",
	//             "amount": "15.00000000",
	//             "type": "0",
	//             "id": "2814205012",
	//         }
	//     ]
	//
	ch <- this.ParseOrders(response, market, since, limit, map[string]any{
		"status": "open",
		"type":   "limit",
	})
	return nil
}
func (this *Bitstamp) GetCurrencyName(code string) any {
	/**
	 * @ignore
	 * @method
	 * @param {string} code Unified currency code
	 * @returns {string} lowercase version of code
	 */
	return strings.ToLower(code)
}
func (this *Bitstamp) IsFiat(code any) any {
	return (IsEqual(code, "USD")) || (IsEqual(code, "EUR")) || (IsEqual(code, "GBP"))
}

/**
 * @method
 * @name bitstamp#fetchDepositAddress
 * @description fetch the deposit address for a currency associated with this account
 * @see https://www.bitstamp.net/api/#tag/Deposits/operation/GetCryptoDepositAddress
 * @param {string} code unified currency code
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} an [address structure]{@link https://docs.ccxt.com/?id=address-structure}
 */
func (this *Bitstamp) FetchDepositAddressAsync(code string, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchDepositAddressBody(ch, code, optionalArgs...)
	return ch
}
func (this *Bitstamp) fetchDepositAddressBody(ch chan any, code string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if EvalTruthy(this.IsFiat(code)) {
		panic(NotSupported(this.Id + " fiat fetchDepositAddress() for " + code + " is not supported!"))
	}
	var name any = this.GetCurrencyName(code)
	// the per-currency implicit methods (privatePostBtcAddress etc.) all route
	// through request(), called here directly to avoid dynamic dispatch

	response := (<-this.RequestAsync(Add(name, "_address/"), "private", "POST", params))
	PanicOnError(response)
	var address *string = this.SafeString(response, "address")
	var tag *string = this.SafeString2(response, "memo_id", "destination_tag")
	this.CheckAddress(address)

	ch <- map[string]any{
		"info":     response,
		"currency": code,
		"network":  nil,
		"address":  address,
		"tag":      tag,
	}
	return nil
}

/**
 * @method
 * @name bitstamp#withdraw
 * @description make a withdrawal
 * @see https://www.bitstamp.net/api/#tag/Withdrawals/operation/RequestFiatWithdrawal
 * @see https://www.bitstamp.net/api/#tag/Withdrawals/operation/RequestCryptoWithdrawal
 * @param {string} code unified currency code
 * @param {float} amount the amount to withdraw
 * @param {string} address the address to withdraw to
 * @param {string} tag
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [transaction structure]{@link https://docs.ccxt.com/?id=transaction-structure}
 */
func (this *Bitstamp) WithdrawAsync(code string, amount any, address any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.withdrawBody(ch, code, amount, address, optionalArgs...)
	return ch
}
func (this *Bitstamp) withdrawBody(ch chan any, code string, amount any, address any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	// For fiat withdrawals please provide all required additional parameters in the 'params'
	// Check https://www.bitstamp.net/api/ under 'Open bank withdrawal' for list and description.
	tag := GetArg(optionalArgs, 0, nil)
	_ = tag
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	var tagWithdrawTagparamsWithdrawTagVariable []any = this.HandleWithdrawTagAndParams(tag, params)
	tagWithdrawTag := GetValue(tagWithdrawTagparamsWithdrawTagVariable, 0)
	var paramsWithdrawTag map[string]any = MapTyped(GetValue(tagWithdrawTagparamsWithdrawTagVariable, 1))
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	this.CheckAddress(address)
	var request map[string]any = map[string]any{
		"amount": amount,
	}
	var currency map[string]any = nil
	var response any = nil
	if !EvalTruthy(this.IsFiat(code)) {
		var name any = this.GetCurrencyName(code)
		if code == "XRP" {
			if !IsEqual(tagWithdrawTag, nil) {
				request["destination_tag"] = tagWithdrawTag
			}
		} else if (code == "XLM") || (code == "HBAR") {
			if !IsEqual(tagWithdrawTag, nil) {
				request["memo_id"] = tagWithdrawTag
			}
		}
		request["address"] = address
		// the per-currency implicit methods (privatePostBtcWithdrawal etc.) all
		// route through request(), called here directly to avoid dynamic dispatch

		response = (<-this.RequestAsync(Add(name, "_withdrawal/"), "private", "POST", this.Extend(request, paramsWithdrawTag)))
		PanicOnError(response)
	} else {
		currency = this.Currency(code)
		request["iban"] = address
		request["account_currency"] = GetValue(currency, "id")

		response = (<-this.PrivatePostWithdrawalOpen(this.Extend(request, paramsWithdrawTag))).Raw
		PanicOnError(response)
	}

	ch <- this.ParseTransaction(response, currency)
	return nil
}

/**
 * @method
 * @name bitstamp#transfer
 * @description transfer currency internally between wallets on the same account
 * @see https://www.bitstamp.net/api/#tag/Sub-account/operation/TransferFromMainToSub
 * @see https://www.bitstamp.net/api/#tag/Sub-account/operation/TransferFromSubToMain
 * @param {string} code unified currency code
 * @param {float} amount amount to transfer
 * @param {string} fromAccount account to transfer from
 * @param {string} toAccount account to transfer to
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [transfer structure]{@link https://docs.ccxt.com/?id=transfer-structure}
 */
func (this *Bitstamp) TransferAsync(code string, amount any, fromAccount any, toAccount string, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.transferBody(ch, code, amount, fromAccount, toAccount, optionalArgs...)
	return ch
}
func (this *Bitstamp) transferBody(ch chan any, code string, amount any, fromAccount any, toAccount string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var currency map[string]any = this.Currency(code)
	var request map[string]any = map[string]any{
		"amount":   this.ParseToNumeric(this.CurrencyToPrecision(code, amount)),
		"currency": ToUpper(currency["id"]),
	}
	var response map[string]any = nil
	if IsEqual(fromAccount, "main") {
		request["subAccount"] = toAccount

		response = MapTyped(PanicOnError((<-this.PrivatePostTransferFromMain(this.Extend(request, params))).Raw))
	} else if toAccount == "main" {
		request["subAccount"] = fromAccount

		response = MapTyped(PanicOnError((<-this.PrivatePostTransferToMain(this.Extend(request, params))).Raw))
	} else {
		panic(BadRequest(this.Id + " transfer() only supports from or to main"))
	}
	//
	//    { status: 'ok' }
	//
	var transfer any = this.ParseTransfer(response, currency)
	AddElementToObject(transfer, "amount", amount)
	AddElementToObject(transfer, "fromAccount", fromAccount)
	AddElementToObject(transfer, "toAccount", toAccount)

	ch <- transfer
	return nil
}
func (this *Bitstamp) ParseTransfer(transfer any, optionalArgs ...any) any {
	//
	//    { status: 'ok' }
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var status *string = this.SafeString(transfer, "status")
	if currency == nil {
		panic(ExchangeError(this.Id + " parseTransfer() could not resolve currency"))
	}
	var result map[string]any = map[string]any{
		"info":        transfer,
		"id":          nil,
		"timestamp":   nil,
		"datetime":    nil,
		"currency":    GetValue(currency, "code"),
		"amount":      nil,
		"fromAccount": nil,
		"toAccount":   nil,
		"status":      this.ParseTransferStatus(status),
	}
	return result
}
func (this *Bitstamp) ParseTransferStatus(status *string) *string {
	var statuses map[string]any = map[string]any{
		"ok":    "ok",
		"error": "failed",
	}
	return this.SafeString(statuses, status, status)
}
func (this *Bitstamp) Nonce() any {
	return this.Milliseconds()
}
func (this *Bitstamp) Sign(path string, optionalArgs ...any) any {
	api := GetArg(optionalArgs, 0, "public")
	_ = api
	var method string = GetArgString(optionalArgs, 1, "GET")
	_ = method
	params := GetArg(optionalArgs, 2, map[string]any{})
	_ = params
	headers := GetArg(optionalArgs, 3, nil)
	_ = headers
	body := GetArg(optionalArgs, 4, nil)
	_ = body
	var apiUrl *string = this.SafeString(GetValue(this.Urls, "api"), api)
	if apiUrl == nil {
		panic(ExchangeError(this.Id + " sign() has no API URL for this endpoint"))
	}
	var url string = *apiUrl + "/"
	url += this.Version + "/"
	url += this.ImplodeParams(path, params)
	var query any = this.Omit(params, this.ExtractParams(path))
	var isPrivatePost bool = (!IsEqual(api, "public")) && (method == "POST")
	// an empty POST triggers an API0020 error, so empty requests send a dummy object
	// https://github.com/ccxt/ccxt/issues/6846
	var emptyPostBody string = this.Urlencode(map[string]any{
		"foo": "bar",
	})
	var postBody string = emptyPostBody
	if len(ObjectKeys(query)) > 0 {
		postBody = this.Urlencode(query)
	}
	var requestBody any = body
	if isPrivatePost {
		requestBody = postBody
	}
	var privateHeaders any = nil
	if IsEqual(api, "public") {
		if len(ObjectKeys(query)) > 0 {
			url += "?" + this.Urlencode(query)
		}
	} else {
		this.CheckRequiredCredentials()
		var xAuth any = Add("BITSTAMP ", this.ApiKey)
		var xAuthNonce string = this.Uuid()
		var xAuthTimestamp string = strconv.FormatInt(this.Milliseconds(), 10)
		var xAuthVersion string = "v2"
		var contentType string = ""
		privateHeaders = map[string]any{
			"X-Auth":           xAuth,
			"X-Auth-Nonce":     xAuthNonce,
			"X-Auth-Timestamp": xAuthTimestamp,
			"X-Auth-Version":   xAuthVersion,
		}
		if method == "POST" {
			contentType = "application/x-www-form-urlencoded"
			AddElementToObject(privateHeaders, "Content-Type", contentType)
		}
		var authBody any = ""
		if (requestBody != nil) && (!IsEqual(requestBody, "")) {
			authBody = requestBody
		}
		var auth any = Add(Add(Add(Add(Add(Add(Add(xAuth, method), strings.Replace(url, "https://", "", 1)), contentType), xAuthNonce), xAuthTimestamp), xAuthVersion), authBody)
		var signature string = this.Hmac(this.Encode(auth), this.Encode(this.Secret), sha256)
		AddElementToObject(privateHeaders, "X-Auth-Signature", signature)
	}
	var requestHeaders any = func() any {
		if IsEqual(api, "public") {
			return headers
		}
		return privateHeaders
	}()
	return map[string]any{
		"url":     url,
		"method":  method,
		"body":    requestBody,
		"headers": requestHeaders,
	}
}
func (this *Bitstamp) HandleErrors(httpCode any, reason any, url any, method any, headers any, body any, response any, requestHeaders any, requestBody any) any {
	if IsEqual(response, nil) {
		return nil
	}
	//
	//     {"error": "No permission found"} // fetchDepositAddress returns this on apiKeys that don't have the permission required
	//     {"status": "error", "reason": {"__all__": ["Minimum order size is 5.0 EUR."]}}
	//     reuse of a nonce gives: { status: 'error', reason: 'Invalid nonce', code: 'API0004' }
	//
	var status *string = this.SafeString(response, "status")
	var error any = this.SafeValue(response, "error")
	if (status != nil && *status == "error") || (!IsEqual(error, nil)) {
		var errors []any = []any{}
		if IsString(error) {
			errors = append(errors, error)
		} else if !IsEqual(error, nil) {
			var keys []string = ObjectKeys(error)
			for i := 0; i < len(keys); i++ {
				var key string = GetValue(keys, i).(string)
				var value any = this.SafeValue(error, key)
				if IsArray(value) {
					errors = this.ArrayConcat(errors, value)
				} else {
					errors = append(errors, value)
				}
			}
		}
		var reasonInner any = this.SafeValue(response, "reason", map[string]any{})
		if IsString(reasonInner) {
			errors = append(errors, reasonInner)
		} else {
			var all []any = SafeListTyped(reasonInner, "__all__")
			for i := 0; i < len(all); i++ {
				errors = append(errors, func() any {
					if i >= 0 && i < len(all) {
						return DerefScalar(all[i])
					}
					return nil
				}())
			}
		}
		var code *string = this.SafeString(response, "code")
		if code != nil && *code == "API0005" {
			panic(AuthenticationError(this.Id + " invalid signature, use the uid for the main account if you have subaccounts"))
		}
		var feedback *string = SafeStringPtr(Add(this.Id+" ", body))
		for i := 0; i < len(errors); i++ {
			var value *string = SafeStringPtr(func() any {
				if i >= 0 && i < len(errors) {
					return DerefScalar(errors[i])
				}
				return nil
			}())
			this.ThrowExactlyMatchedException(this.Exceptions["exact"], value, feedback)
			this.ThrowBroadlyMatchedException(this.Exceptions["broad"], value, feedback)
		}
		panic(ExchangeError(feedback))
	}
	return nil
}

func NewBitstamp(userConfig map[string]any) *Bitstamp {
	p := newBitstamp()
	p.Init(userConfig)
	return p
}

func (this *Bitstamp) Init(userConfig map[string]any) {
	this.Exchange = Exchange{}
	this.Exchange.DerivedExchange = this
	this.Exchange.InitParent(userConfig, this.Describe().(map[string]any), this)
	this.exchangeTyped = NewExchangeTyped(&this.Exchange)
}

